            T("ModMarrowHound", "Marrow Hound", "Two snapping bites; may bleed", "Howl: a bleed ring round you, then sprint", "Run faster at a bleeding hero\nWhen hurt, a bone pile heals you a great deal"); Group["ModMarrowHound"] = "ossivar";
            T("ModOssBarghest", "Barghest", "Two rending bites; may bleed", "Pounce (can't be hit): land past him, facing him", "Bite him from behind to hit harder\nYour eyes flare while you are behind him"); Group["ModOssBarghest"] = "ossivar";
            T("ModOssBoneMammoth", "Bone Mammoth", "Tusk sweep with knockback", "Cross Quake: rear, stamp, spikes along a cross", "Your stamp splits the floor in a cross\nEach footfall jolts the floor round your foot"); Group["ModOssBoneMammoth"] = "ossivar";
            T("ModOssCarrionRoc", "Carrion Roc", "Diving beak stab; may bleed", "Airlift: fly a friend or a pile onto the hero", "Fly a friend to the hero and drop them on him\nThey land with a plate. Their shadow marks the spot"); Group["ModOssCarrionRoc"] = "ossivar";
            T("ModOssCarrionSaint", "Carrion Saint", "Send a perched crow at the hero", "Murder: every perched crow flies as a wall", "Your perched crows are your shots. Bones bring more\nUp to four perch, and lost ones come back"); Group["ModOssCarrionSaint"] = "ossivar";
            T("ModOssCarrionVulture", "Carrion Vulture", "Swoop through the hero, raking; may bleed", "Plummet (can't be hit): drop on his marked spot", "When he's below half health, you're faster\nand your rake always bleeds"); Group["ModOssCarrionVulture"] = "ossivar";
            T("ModOssCerberus", "Cerberus", "Three heads bite at once in a fan", "Three gas cones sweep in and poison", "Your three breaths sweep in and meet on him\nThe outer heads glow first: the way out is back"); Group["ModOssCerberus"] = "ossivar";
            T("ModOssCharnelRider", "Charnel Rider", "Wide lance sweep in front", "Joust: gallop a long way or into a wall, then wheel", "Badly hurt, your horse falls: fight on foot\nOn foot: throw your lance, run in with a thrust"); Group["ModOssCharnelRider"] = "ossivar";
            T("ModOssChurchGrim", "Church Grim", "Long lunging bite", "Graveward Lunge: run through him; may bleed", "Once, when slain, you rise from your bones\nIf he stands on your bones meanwhile, you're gone"); Group["ModOssChurchGrim"] = "ossivar";
            T("ModOssCoffinBearer", "Coffin Bearer", "Coffin slam in front", "Whirl: up to three hits, then you are dizzy", "Press again mid-whirl to let the coffin fly\nIt flies out on its chain and you skip the daze"); Group["ModOssCoffinBearer"] = "ossivar";
            T("ModOssGravedigger", "Gravedigger", "Spade swing that flings grave dirt", "Unearth: dig two bone piles out of the floor", "Two quick spade hits bury him to the knees\nBuried, he moves slowly for a moment"); Group["ModOssGravedigger"] = "ossivar";
            T("ModOssGravetusk", "Gravetusk", "Tusk gore that tosses the hero back", "Charge: trampled piles burst into shards", "Your charge bends to a bleeding hero\nPiles ahead of your charge glow before they burst"); Group["ModOssGravetusk"] = "ossivar";
            T("ModOssMarrowWyrm", "Marrow Wyrm", "Long-necked lunge; may bleed", "Neck Lash: cock back, then sweep the arc in front", "Piles near you give two plates, not one\nRed lines show the piles you filled with marrow"); Group["ModOssMarrowWyrm"] = "ossivar";
            T("ModOssRazorback", "Razorback", "Tusk slash; may bleed", "Skid: fire every raised quill ahead in a fan", "Run to raise your quills\nEach second of standing still lowers a quill"); Group["ModOssRazorback"] = "ossivar";
            T("ModOssSpinehook", "Spinehook", "Hook rake; may bleed", "Harpoon: it bites the hero or a bone pile", "Harpoon a bone pile and reel it in through him\nA pile reeled in to you becomes a plate"); Group["ModOssSpinehook"] = "ossivar";
            T("ModOssTombwright", "Tombwright", "Mallet smash; knocks over a headstone it hits", "Raise three headstones in a line at the hero", "Raise headstones, then mallet them over onto him\nA falling stone topples the next, then breaks to bones"); Group["ModOssTombwright"] = "ossivar";
            T("ModOssuary", "The Ossuary", "Fists slam a ring of spikes ahead", "Ribcage: six ribs burst up round him", "Cage him in ribs. He breaks one to get out\nYou hold up to three plates: soak his way out"); Group["ModOssuary"] = "ossivar";
            T("ModOssuaryPriest", "Ossuary Priest", "Slow marrow bolt that homes in on the hero", "Raise nearby bone piles as rats", "Bones come to you from further, and faster\nThey wait at your feet for Raise. Kin may eat them"); Group["ModOssuaryPriest"] = "ossivar";
            T("ModRattlebones", "Rattlebones", "Lob your skull: it stays where it lands and bites", "Collapse into a bone pile and heal", "While your skull is out, only the skull can be hit\nSwipe headless to call your skull home"); Group["ModRattlebones"] = "ossivar";
            // tips_silver.json
            T("ModSilverAstrarch", "The Astrarch", "Starshot: leaves a star on the floor", "Join your stars: starfall hits inside them", "Three or more stars out: you take less damage.\nLegendary silver unique: a very rare upgrade"); Group["ModSilverAstrarch"] = "silver";
            T("ModSilverCometStag", "Comet Stag", "Antler gore", "Comet: fly ahead, rebounding off three walls", "Run straight for a bursting gore\nSilver unique: only from a silver ghost's orbs"); Group["ModSilverCometStag"] = "silver";
            T("ModSilverMoonwarden", "Moonwarden", "Crescent glaive sweep", "Moonfall: strike harder as the moon fills", "Your moon waxes a phase at a time, New to Full.\nSilver unique: only from a silver ghost's orbs"); Group["ModSilverMoonwarden"] = "silver";
            // tips_statuemon.json
            T("ModStmCaryatid", "Caryatid", "Smash your stone capital down in front", "Raise a column under the hero; it stands a while", "Beside one of your columns you take less damage.\nTwo columns at most; the oldest crumbles first"); Group["ModStmCaryatid"] = "statuemon";
            T("ModStmGambit", "Gambit", "Rear up and slam your head down", "Knight's Tour: three L-shaped leaps", "A landing on the hero puts him in check.\nSlam him while in check for checkmate"); Group["ModStmGambit"] = "statuemon";
            T("ModStmGrotesque", "Grotesque", "Rake with your stone talons", "Turn to stone: no harm; hits return as shards", "First killing blow: crumble to rubble, then reform\nwith some health. Your ember ring shows it is still to come"); Group["ModStmGrotesque"] = "statuemon";
            T("ModStmLachrymosa", "Lachrymosa", "Lament: rake with both hands", "Lights Out: the room goes dark; none see you", "Watched, you turn to slow stone\nUnseen, you are swift and fierce"); Group["ModStmLachrymosa"] = "statuemon";
            T("ModStmSixfold", "Sixfold Idol", "A random weapon a swing: sword, mace, spear, flail", "A rite of jade: Ring, Fan, Spiral or Cross", "Your next rite's sigil glows over you when ready.\nAll four rites come once before any of them repeats"); Group["ModStmSixfold"] = "statuemon";
            // tips_sylvene.json
            T("ModBloomWitch", "Bloom Witch", "Pollen lance: pierces, long range, may poison", "Graft a ripe pod onto your kin and yourself", "Graft ripe pods onto your kin's heads\nDeath drops a seed that ripens into a poison pod"); Group["ModBloomWitch"] = "sylvene";
            T("ModBrambleKnight", "Bramble Knight", "Two-hit thorn sweep, may bleed", "Overgrow: four thorn patches burst up round you", "Your sweep's tip plants a thorn patch\nDeath drops a seed that ripens into a poison pod"); Group["ModBrambleKnight"] = "sylvene";
            T("ModRotMother", "The Rot Mother", "Roots erupt under the hero twice, may root", "Sprouting: three Sprouts burst up round the hero", "Each pod that bursts on him heals you\nDeath drops a seed that ripens into a poison pod"); Group["ModRotMother"] = "sylvene";
            T("ModRotfly", "Rotfly", "Spit a poison glob, mid range", "Buzz Bomb: dive, burst a poison puff, climb back", "Spit that misses lands as a seed\nDeath drops a seed that ripens into a poison pod"); Group["ModRotfly"] = "sylvene";
            T("ModSporeling", "Sporeling", "Puff a short cloud of poison spores", "Scatter: shake two seeds out of your cap", "Seeds next to you ripen much faster\nDeath drops a seed that ripens into a poison pod"); Group["ModSporeling"] = "sylvene";
            T("ModSprout", "Sprout", "Puff a tiny poison spore cloud", "none", "Burst up through the floor round the hero"); Group["ModSprout"] = "sylvene";
            T("ModSylBlightBellows", "Blight Bellows", "Bladder lob: bounces three times, then bursts", "Gas Lanes: pump three lanes of gas; turn between", "Your bladders bounce three times, puffing gas\nDeath drops a seed that ripens into a poison pod"); Group["ModSylBlightBellows"] = "sylvene";
            T("ModSylBloatfly", "Bloatfly", "Retch a cone of poison bile", "Bile Rain: retch straight down on him; steer it", "In your bile, his poison lasts longer\nDeath drops a seed that ripens into a poison pod"); Group["ModSylBloatfly"] = "sylvene";
            T("ModSylBriarBehemoth", "Briar Behemoth", "Tusk hook, may bleed", "Charge; your bush swings in as you stop", "Your dragged bush swings in when you turn or stop\nDeath drops a seed that ripens into a poison pod"); Group["ModSylBriarBehemoth"] = "sylvene";
            T("ModSylBriarChampion", "Briar Champion", "Lance thrust, may bleed", "Lunge: plant your feet and thrust further", "Each hit grows your lance. Each hit taken trims it\nDeath drops a seed that ripens into a poison pod"); Group["ModSylBriarChampion"] = "sylvene";
            T("ModSylBriarWyrm", "Briar Wyrm", "Mace tail: hits in front, then behind you", "Thorn Spiral: spin out thorns in two arms", "Your mace hits in front, then behind you\nDeath drops a seed that ripens into a poison pod"); Group["ModSylBriarWyrm"] = "sylvene";
            T("ModSylCarrionLily", "Carrion Lily", "Stalk lunge: a poison bite", "Corpse Bloom: a wide cone of rot", "Planted, you heal and reach far. Uproot to move\nDeath drops a seed that ripens into a poison pod"); Group["ModSylCarrionLily"] = "sylvene";
            T("ModSylCarrionQueen", "Carrion Queen", "Proboscis stab, may poison", "Proboscis Dive: a long dive you steer", "Your drone keeps dazing him: stay close\nDeath drops a seed that ripens into a poison pod"); Group["ModSylCarrionQueen"] = "sylvene";
            T("ModSylCordyceps", "Cordyceps Saint", "Spine flick, long range, may poison", "Infect your kin or yourself", "Infect your kin: they fight on after death\nDeath drops a seed that ripens into a poison pod"); Group["ModSylCordyceps"] = "sylvene";
            T("ModSylGallWasp", "Gall Wasp", "Needle that plants a seed where it lands", "Dart through the hero, dropping two seeds", "Your seeds ripen faster\nDeath drops a seed that ripens into a poison pod"); Group["ModSylGallWasp"] = "sylvene";
            T("ModSylNightshade", "Nightshade", "Berry toss: splits into three, may poison", "Shade Garden: hide your pods, plant two by him", "Your pods go unseen a while. He has to guess\nDeath drops a seed that ripens into a poison pod"); Group["ModSylNightshade"] = "sylvene";
            T("ModSylPollenMonarch", "Pollen Monarch", "Wing clap: three pollen darts in a fan", "Pollen Storm: a wide cloud ahead, and four seeds", "Dusted, he sets off pods from further away\nDeath drops a seed that ripens into a poison pod"); Group["ModSylPollenMonarch"] = "sylvene";
            T("ModSylPuffball", "Puffball Brute", "Fist slam in a ring of spores", "Bounce at the hero, steered; land in a spore ring", "Knocked into a wall, you bounce back at him\nDeath drops a seed that ripens into a poison pod"); Group["ModSylPuffball"] = "sylvene";
            T("ModSylShambler", "Shambler", "Puff a poison spore cloud", "none", "You stagger on a moment, then burst into seeds"); Group["ModSylShambler"] = "sylvene";
            T("ModSylSower", "The Sower", "Seed shot: plants a seed where it lands", "Strafe across his front, sowing a row of seeds", "Seeds from one pass burst together\nDeath drops a seed that ripens into a poison pod"); Group["ModSylSower"] = "sylvene";
            T("ModSylSporeHusk", "Spore Husk", "Club smash that bursts a poison cloud", "Spore Belch: a wide cone of poison spores", "Your smash bursts every ripe pod nearby\nDeath drops a seed that ripens into a poison pod"); Group["ModSylSporeHusk"] = "sylvene";
            T("ModSylStrangler", "Strangler Vine", "Lunging bite", "Lasso a pod or seed near you and sling it at him", "Lasso a pod and sling it at him\nDeath drops a seed that ripens into a poison pod"); Group["ModSylStrangler"] = "sylvene";
            T("ModThornbiter", "Thornbiter", "Long vine whip that may bleed", "Root Run: roots race at the hero and root him", "Your roots plant a seed where they stop\nDeath drops a seed that ripens into a poison pod"); Group["ModThornbiter"] = "sylvene";
            // tips_umbrael.json
            T("ModArgusMoth", "Argus Moth", "A fan of three eye scales", "Scale Storm: three widening waves of scales", "Shots near you veer into your wings, weakened\nYour basic hits echo a beat later"); Group["ModArgusMoth"] = "umbrael";
            T("ModBristleback", "Bristleback", "Lob three nails, left as caltrops", "Shake: a horseshoe of nails behind and aside", "His shots stick in you. Your next lob throws them\nYour basic hits echo a beat later"); Group["ModBristleback"] = "umbrael";
            T("ModEclipseWyrm", "Eclipse Wyrm", "Void head bites, then glass head, may daze", "Eclipse: swallow your glass head", "Eclipse: a black disc with a burning ring\nYour basic hits echo a beat later"); Group["ModEclipseWyrm"] = "umbrael";
            T("ModGlassSeraph", "Glass Seraph", "Three glass feathers that ricochet", "Prism: five feathers, each splits on a wall", "Echoes near you bend toward him\nYour basic hits echo a beat later"); Group["ModGlassSeraph"] = "umbrael";
            T("ModGlassWidow", "Glass Widow", "Front legs stab down", "Glaze Web lands on his spot a beat on, roots", "Glazed, his next hit taken cracks for more\nYour basic hits echo a beat later"); Group["ModGlassWidow"] = "umbrael";
            T("ModGlassmoth", "Glassmoth", "Two glass scales in a V", "Glitter cloud drifts at the hero and slows him", "Echoes inside your glitter hit at full damage\nYour basic hits echo a beat later"); Group["ModGlassmoth"] = "umbrael";
            T("ModGlimmer", "Glimmer", "A mirror shard that ricochets off walls", "Two decoys flick shards, then burst", "Shards hit harder after a wall bounce\nYour basic hits echo a beat later"); Group["ModGlimmer"] = "umbrael";
            T("ModGlimmerDecoy", "Glimmer Decoy", "Flick a weak mirror shard", "none", "Bursts after a while, or when killed"); Group["ModGlimmerDecoy"] = "umbrael";
            T("ModGlitterswarm", "Glitterswarm", "The swarm surges ahead and bites", "Surge through the hero on a line you steer", "Your Surge echoes along its path a beat later\nYour basic hits echo a beat later"); Group["ModGlitterswarm"] = "umbrael";
            T("ModGloamcoil", "Gloamcoil", "Rearing lunge bite", "Dash along the floor, leaving darkness pools", "Darkness you lie in spreads\nYour basic hits echo a beat later"); Group["ModGloamcoil"] = "umbrael";
            T("ModGloomLurker", "Gloom Lurker", "Lunging bite, harder from hiding, may daze", "Breathe a darkness cloud that hides your kin", "Keep still or stay dark to hide. Bite from hiding\nYour basic hits echo a beat later"); Group["ModGloomLurker"] = "umbrael";
            T("ModHollowKing", "The Hollow King", "A great eclipse cleave", "Throw your crown down by the hero", "Throw your crown: your echoes strike there\nYour basic hits echo a beat later"); Group["ModHollowKing"] = "umbrael";
            T("ModHourglass", "Hourglass", "Spit a shard of fused sand", "Rewind: soon after, snap back to your mark", "Snap back to your mark, health and all\nYour basic hits echo a beat later"); Group["ModHourglass"] = "umbrael";
            T("ModMirrorWitch", "Mirror Witch", "A long-lived bolt that banks off walls", "Set a mirror pane between you and the hero", "Your mirror bounces your bolts and his shots\nYour basic hits echo a beat later"); Group["ModMirrorWitch"] = "umbrael";
            T("ModNailshade", "Nailshade", "Fling a fan of three glass nails", "Pin roots him, then re-form by him and rake", "Each fan that hits throws the next one tighter\nYour basic hits echo a beat later"); Group["ModNailshade"] = "umbrael";
            T("ModPendulum", "The Pendulum", "Heavy swing: the blade goes all the way round", "Stop the Clock: he and his shots slow near you", "Your blade swings on its own. Time it\nYour basic hits echo a beat later"); Group["ModPendulum"] = "umbrael";
            T("ModSandWraith", "Sand Wraith", "Hurl a fist of sand", "Time Out: an hourglass hangs over him", "Your hits are held, then fall as one column\nYour basic hits echo a beat later"); Group["ModSandWraith"] = "umbrael";
            T("ModShadeImp", "Shade Imp", "Two quick claw rakes", "Smoke Step: blink at the hero through smoke", "In darkness, your echoes come faster\nYour basic hits echo a beat later"); Group["ModShadeImp"] = "umbrael";
            T("ModSundered", "The Sundered", "Two sabres scissor shut ahead", "Rejoin: your pale half rushes home, cutting", "Your pale half rushes back to you through him\nYour basic hits echo a beat later"); Group["ModSundered"] = "umbrael";
            T("ModTwinned", "The Twinned", "Slash ahead, then your back body slashes behind", "Swap places with the hero, then cut", "After a swap, your cut echoes in both spots\nYour basic hits echo a beat later"); Group["ModTwinned"] = "umbrael";
            T("ModUnblinking", "The Unblinking", "A short straight gaze beam", "Lights Out: shut your eye; darkness falls round you", "When your eye opens, a moving hero is dazed\nYour basic hits echo a beat later"); Group["ModUnblinking"] = "umbrael";
            T("ModUndertow", "The Undertow", "Rearing bite, may poison", "Lurk Beneath an ally, biting out", "Hide under a friend's feet and bite from there\nYour basic hits echo a beat later"); Group["ModUndertow"] = "umbrael";
            // tips_vhorrul.json
            T("ModAshMoth", "Ash Moth", "Ash Puff: a drifting ash cloud that may daze", "Flame Dive: dive ahead, bending toward fire", "Near fire you fly faster\nYour death leaves a pyre that cools to wax"); Group["ModAshMoth"] = "vhorrul";
            T("ModCandelabra", "Candelabra", "Five Flames: a fan of five candle flames", "Vigil: plant and light the wax near you", "Your flames fork in two when they cross wax\nYour death leaves a pyre that cools to wax"); Group["ModCandelabra"] = "vhorrul";
            T("ModChandler", "Chandler", "Molten Glob: lands as a burning pool", "Pour: a line of unlit wax ahead", "Pour a line, wait, then shoot it: it all goes up\nThe flame runs down the line to him"); Group["ModChandler"] = "vhorrul";
            T("ModLanternWraith", "Lantern Wraith", "Soul Orb: an orb that bursts where it stops", "Take the Light: a cone that steals his soul flame", "Steal his soul flame: he hits softer\nYour orbs hit harder while you hold it"); Group["ModLanternWraith"] = "vhorrul";
            T("ModMothMatron", "Moth Matron", "Ember Rake: leaves an ash puff that may daze", "Moth Lamp: let loose three ember moths", "Your moths hunt a burning hero. Else they drift\nDrifting moths light any wax they touch"); Group["ModMothMatron"] = "vhorrul";
            T("ModTallowColossus", "Tallow Colossus", "Fist One-Two: two huge blows", "Topple: rear up and fall flat on him", "Soak up wax to grow. Fire melts your layers off\nEach layer: harder fists and a longer Topple"); Group["ModTallowColossus"] = "vhorrul";
            T("ModTallowGrub", "Tallow Grub", "Wax Spit: a glob that skids and pools, and slows", "Melt: glide as a puddle (can't be hit), then rise", "Melt, glide your puddle under him, then rise\nFire on your puddle burns you out"); Group["ModTallowGrub"] = "vhorrul";
            T("ModVhAshSeraph", "Ashen Seraph", "Lance Thrust: a long cinder lance", "Ash to Ash: fires near you go out as ash clouds", "Beat fires out: each becomes a dazing ash cloud\nThe clouds drift after him"); Group["ModVhAshSeraph"] = "vhorrul";
            T("ModVhBroodMother", "Grub Mother", "Head Slam: leaves a wax pool", "Brood Spit: three grublings land by the hero", "Grubs that crawl through fire burst into flame\nDying lets three grublings loose"); Group["ModVhBroodMother"] = "vhorrul";
            T("ModVhCandleWyrm", "Candle Wyrm", "Rear Strike: strike down just ahead", "Wick Coil: race a ring of fire round the hero", "Coil round him. The closed ring tightens\nYou swim in wax like the Wickworm"); Group["ModVhCandleWyrm"] = "vhorrul";
            T("ModVhChandelier", "Grand Chandelier", "Wheel: burn all round you", "Drip and Flare: drip a ring of wax, then light it", "High on your chain, blades can't reach you\nYou bob low, then high, in turn"); Group["ModVhChandelier"] = "vhorrul";
            T("ModVhFuseScorpion", "Fuse Scorpion", "Twin Snap: both claws", "Light the Fuse: a spark runs his footsteps", "Your fuse follows his footsteps. Wax speeds it up\nThe spark bursts on him, or burns out"); Group["ModVhFuseScorpion"] = "vhorrul";
            T("ModVhPyreTick", "Pyre Tick", "Barbed Bite: gives the hero a fever", "Ember Spray: five drops of burning blood", "Your bite gives him fever: wax he steps on lights\nYour death leaves a pyre that cools to wax"); Group["ModVhPyreTick"] = "vhorrul";
            T("ModVhPyreWarden", "Pyre Warden", "Censer Smash: an ember ring that lights wax", "Stoke: the fire near him spreads in three rings", "Pyres near you never cool\nNo fire near? Stoke lights a pyre at your feet"); Group["ModVhPyreWarden"] = "vhorrul";
            T("ModVhReliquary", "Votive Reliquary", "Votive Fan: three flames that light wax", "Anoint: holy oil on every kin near you", "Anoint your kin: their next two hits burn\nAnointed, your own fan throws five flames"); Group["ModVhReliquary"] = "vhorrul";
            T("ModVhRenderer", "Tallow Renderer", "Ladle Fling: boiling tallow that may slow", "Boil Over: a wave of tallow rolls ahead", "Tip the pot and ride the wave in\nRiding, you can't be knocked back"); Group["ModVhRenderer"] = "vhorrul";
            T("ModVhTallowSow", "Tallow Sow", "Fat Spray: three drops of hot fat that may slow", "Lay three wax eggs: soon each spits at the hero", "Wallow in wax: his shots glance off your coat\nFire melts the coat. Unlit wax heals you"); Group["ModVhTallowSow"] = "vhorrul";
            T("ModVhWickHag", "Wick Hag", "Hex Flame: a flicked flame that lights wax", "Poppet: set down a wax poppet of the hero", "Burn his poppet and he feels it\nHex flames go for the poppet while he keeps away"); Group["ModVhWickHag"] = "vhorrul";
            T("ModVhWickworm", "Wickworm", "Rearing Bite: short reach", "Drip Road: slither fast, laying wax", "Swim in wax unseen. Only your candles show\nLit wax burns you out. Death leaves a pyre"); Group["ModVhWickworm"] = "vhorrul";
            T("ModWaxenKnight", "Waxen Knight", "Three cuts, and the overhead spills wax", "Seal: wax over yourself, then crack off as a ring", "Seal throws your flames out as a ring\nBurning: cuts burn, but you take more harm"); Group["ModWaxenKnight"] = "vhorrul";
            T("ModWickling", "Wickling", "Flare Bite: a hop-lunge bite that may burn", "Gutter Dash: sprint, leaving fire", "Touch fire to flare your tail up\nA flared bite hits harder and always burns"); Group["ModWickling"] = "vhorrul";
            // tips_ysveld.json
            T("ModYsvBride", "The Winter Bride", "Breathe a cone of frost ahead", "Sweep your train of snow round you", "An ally dies near you: widowed, two pips a hit\nThree frost pips pin the hero"); Group["ModYsvBride"] = "ysveld";
            T("ModYsvBroodling", "Broodling", "Small frost bite; fills a frost pip on the hero", "none", "Melts away after a while"); Group["ModYsvBroodling"] = "ysveld";
            T("ModYsvColossus", "Rime Colossus", "Two-fisted slam with a frost quake ahead", "Pave an ice road to the hero, belly-slide down it", "On ice: no knockback, and you hit harder\nYou run faster on ice"); Group["ModYsvColossus"] = "ysveld";
            T("ModYsvEmpress", "The Pale Empress", "Fire a wide fan of five aurora motes", "Blizzard drifts after the hero", "While you live, the blizzard comes more often\nYou run faster on ice"); Group["ModYsvEmpress"] = "ysveld";
            T("ModYsvGeode", "The Geode", "Dome slam", "Split the seam and fire four crystals in a fan", "At half health you split into two fast halves\nThree frost pips pin the hero"); Group["ModYsvGeode"] = "ysveld";
            T("ModYsvGeodeHalf", "Geode Half", "Dome slam", "none", "Half a Geode: faster, but takes more damage"); Group["ModYsvGeodeHalf"] = "ysveld";
            T("ModYsvGlasswing", "Glasswing", "Glass scythe slash", "Shut yourself in glass. Three cracks break it", "Hatch unbroken to heal\nThree frost pips pin the hero"); Group["ModYsvGlasswing"] = "ysveld";
