            T("ModYsvHoarclaw", "Hoarclaw", "Ice pincer snap", "Seize the hero, then hurl him away", "Hurled across ice, he slides into the wall\nYou run faster on ice"); Group["ModYsvHoarclaw"] = "ysveld";
